158	void StorageView::read(
159	        QueryPlan & query_plan,
160	        const Names & column_names,
161	        const StorageSnapshotPtr & storage_snapshot,
162	        SelectQueryInfo & query_info,
163	        ContextPtr context,
164	        QueryProcessingStage::Enum /*processed_stage*/,
165	        const size_t /*max_block_size*/,
166	        const size_t /*num_streams*/)
167	{
168	    ASTPtr current_inner_query = storage_snapshot->metadata->getSelectQuery().inner_query;
169	
170	    if (query_info.view_query)
171	    {
172	        if (!query_info.view_query->as<ASTSelectWithUnionQuery>())
173	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Unexpected optimized VIEW query");
174	        current_inner_query = query_info.view_query->clone();
175	    }
176	
177	    auto options = SelectQueryOptions(QueryProcessingStage::Complete, 0, false, query_info.settings_limit_offset_done);
178	
179	    if (context->getSettingsRef()[Setting::allow_experimental_analyzer])
180	    {
181	        auto view_context = getViewContext(context, storage_snapshot);
182	        InterpreterSelectQueryAnalyzer interpreter(current_inner_query, view_context, options, column_names, query_info.filter_actions_dag.get());
183	        interpreter.addStorageLimits(*query_info.storage_limits);
184	        query_plan = std::move(interpreter).extractQueryPlan();
185	    }
186	    else
187	    {
188	        auto view_context = getViewContext(context, storage_snapshot);
189	        InterpreterSelectWithUnionQuery interpreter(current_inner_query, view_context, options, column_names);
190	        interpreter.addStorageLimits(*query_info.storage_limits);
191	        interpreter.buildQueryPlan(query_plan);
192	    }
193	
194	    /// It's expected that the columns read from storage are not constant.
195	    /// Because method 'getSampleBlockForColumns' is used to obtain a structure of result in InterpreterSelectQuery.
196	    ActionsDAG materializing_actions(query_plan.getCurrentHeader()->getColumnsWithTypeAndName());
197	    materializing_actions.addMaterializingOutputActions(/*materialize_sparse=*/ true);
198	
199	    auto materializing = std::make_unique<ExpressionStep>(query_plan.getCurrentHeader(), std::move(materializing_actions));
200	    materializing->setStepDescription("Materialize constants after VIEW subquery");
201	    query_plan.addStep(std::move(materializing));
202	
203	    /// And also convert to expected structure.
204	    const auto & expected_header = storage_snapshot->getSampleBlockForColumns(column_names);
205	    const auto & header = query_plan.getCurrentHeader();
206	
207	    const auto * select_with_union = current_inner_query->as<ASTSelectWithUnionQuery>();
208	    if (select_with_union && hasJoin(*select_with_union) && changedNullabilityOneWay(*header, expected_header))
209	    {
210	        throw DB::Exception(ErrorCodes::INCORRECT_QUERY,
211	                            "Query from view {} returned Nullable column having not Nullable type in structure. "
212	                            "If query from view has JOIN, it may be cause by different values of 'join_use_nulls' setting. "
213	                            "You may explicitly specify 'join_use_nulls' in 'CREATE VIEW' query to avoid this error",
214	                            getStorageID().getFullTableName());
215	    }
216	
217	    auto convert_actions_dag = ActionsDAG::makeConvertingActions(
218	            header->getColumnsWithTypeAndName(),
219	            expected_header.getColumnsWithTypeAndName(),
220	            ActionsDAG::MatchColumnsMode::Name,
221	            context);
222	
223	    auto converting = std::make_unique<ExpressionStep>(query_plan.getCurrentHeader(), std::move(convert_actions_dag));
224	    converting->setStepDescription("Convert VIEW subquery result to VIEW table structure");
225	    query_plan.addStep(std::move(converting));
226	}
